/*
 * 墓碑 service worker。
 *
 * 站点早先那版（Jekyll + Chirpy）开着 pwa.enabled，给每个访问过的人在
 * /sw.min.js 注册了一个带缓存的 service worker。换成 Astro 之后这个文件
 * 不再生成，但浏览器里的注册还在，会继续拿缓存里的旧页面顶掉新站。
 *
 * 这里用同一个地址放一个替身：装上之后清空所有 cache、注销自己，再把已经
 * 打开的页面刷一遍。浏览器每次导航都会重新拉 SW 脚本做更新检查，所以老访客
 * 下次打开站点就会自动恢复。
 *
 * 等确认没人再带着旧 registration，可以删掉这个文件。
 */
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();

      const windows = await self.clients.matchAll({ type: 'window' });
      for (const win of windows) win.navigate(win.url);
    })(),
  );
});

// 故意不注册 fetch 事件：所有请求直接走网络。
